#!/usr/bin/env python3
"""Turn 35 Wave 100: WHAT TIER 1 ACTUALLY FEELS LIKE, AND THE NAMED STADIUMS.

Wave 100's centrepieces:

1. THE TIER 1 COMPLAINT, ENUMERATED - which turns the corpus's "scripting" discussion from a
   theory into a list of specific, recognisable behaviours. Players at Tier 1 report their
   players getting **locked in place**, **running side to side instead of forwards**, **running
   away from the ball when passed to**, and **running towards a defender without input**. A
   second source adds the sharpest version: the game **overrides whatever formation you
   choose**, so pausing to change shape fixes nothing. If those behaviours are real, they are
   the things a Tier 1 player must recognise rather than fight.

2. THE NAMED STADIUMS, which the corpus's capacity ladder was missing. DLS26 ships real-world
   grounds with real capacities - Brighton's American Express Stadium at 43,056, Fulham's
   Craven Cottage at 29,246. So the stadium build is not an abstract seat count; it is a
   choice of named ground, and the division gates map onto specific clubs.

3. THE FANZONE'S REAL BENEFIT, phrased precisely at last: it grants **structural discounts on
   Stadium expansions** - not a general gem discount, a discount on the sector builds that
   make up the capacity ladder. That is a much more useful statement than "stadium discounts",
   because it prices the Fanzone against the ~10,000-coin stadium project directly.
"""
import json, os, datetime
ROOT='/home/user/dls26-omega'
EVIDENCE_INDEX=os.path.join(ROOT,'docs/continuity/a7e23a6b/evidence/index.jsonl')
CLAIMS_PATH=os.path.join(ROOT,'kb/claims.jsonl')
RAW_DIR=os.path.join(ROOT,'evidence/raw','turn35_w100')

last_ev=max(int(json.loads(l)['evidence_id'].split('-')[1]) for l in open(EVIDENCE_INDEX) if l.strip() and json.loads(l)['evidence_id'].startswith('EV-'))
last_cl=max(int(json.loads(l)['claim_id'].split('-')[1]) for l in open(CLAIMS_PATH) if l.strip() and json.loads(l)['claim_id'].startswith('CLAIM-'))
ev_id=last_ev+1; cl_id=last_cl+1

def new_ev(origin, summary, artifact_path, vol, quality="community"):
    global ev_id
    eid=f'EV-{ev_id:03d}'
    rec={"evidence_id":eid,"parent_claim_id":None,"captured_at":datetime.datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ'),
         "origin_method":origin,"artifact_path":artifact_path,"volume_label":vol,"source_quality":quality,"summary":summary}
    with open(EVIDENCE_INDEX,'a') as f: f.write(json.dumps(rec)+'\n')
    ev_id+=1; return eid

def add_claim(text, conf, domain, evs, notes=""):
    global cl_id
    cid=f'CLAIM-{cl_id:04d}'
    rec={"claim_id":cid,"text":text,"confidence":conf,"domain":domain,"supporting_evidence":evs,"audit_status":"unchecked","notes":notes}
    with open(CLAIMS_PATH,'a') as f: f.write(json.dumps(rec)+'\n')
    cl_id+=1; return cid

os.makedirs(RAW_DIR,exist_ok=True)

e_t1=new_ev("r/DreamLeagueSoccer 1epc2t7 'Tier 2 Vs Tier 1 Discussion!' (the Tier 1 rigging complaints enumerated - players locked in place, running side to side, running away from the ball, running towards a defender without input - and the 'rigging is quite uniform in tier 1 and 2' claim with the three-attempts-to-win figure), r/DreamLeagueSoccer 16n9is4 (20 Sep 2023 - the Discovery9981 'S' and 'W' handicap pattern, including the claim that the game overrides whatever formation you choose), r/DreamLeagueSoccer 16l5a9w (17 Sep 2023 - the advance-or-get-harder dynamic, already in the corpus at CLAIM-1427), r/DreamLeagueSoccer 1dxkgym (7 Jul 2024 - the once-every-4-seasons Tier 1 cadence and the exploit-abuser influx at Tier 1), r/DreamLeagueSoccer 1p4eshq (23 Nov 2025 - the non-maxed advantage at Tier 2), r/DreamLeagueSoccer 1q626f2 'DLS live is scripted against skilled players and maxed teams' (7 Jan 2026 - the unmaxed-vs-maxed career difference and the retention-handicap theory), r/DreamLeagueSoccer 1phcvdv (8 Dec 2025 - the luck-over-skill sentiment), r/DreamLeagueSoccer 1q1jmpd (2 Jan 2026 - the counter-dissent that reaching Tier 1 is simple and boring), r/DreamLeagueSoccer 1ha876r (9 Dec 2024 - the tier-15 relegation with every opponent maxed), r/DreamLeagueSoccer 1ghbsed (1 Nov 2024 - the deliberate relegation to a farming tier as a mental-health break), r/DreamLeagueSoccer 1gf89h3 (29 Oct 2024 - tier 1 highest, 20 lowest, and the tier-8-harder-than-tier-5 variance), r/DreamLeagueSoccer rsrzfa (31 Dec 2021 - the tier 11 cliff, already partly in the corpus), dlsinside.com/stadiums (the DLS26 named stadiums with capacities, build 13.420 code 159, last update 2026-09-01), the App Store version history (official - the Fanzone wording), thesoccerera.com and dlskits.mobi (the Fanzone's clan bonuses and structural stadium discounts), gtrmod.com (the Fanzone at level 5)",
    "WHAT TIER 1 ACTUALLY FEELS LIKE, THE NAMED STADIUMS, AND THE FANZONE'S REAL BENEFIT. (1) THE TIER 1 COMPLAINT, ENUMERATED - which turns the corpus's scripting discussion from a theory into a list of recognisable behaviours: '**Tier 1 is a bunch of horseshit argue with a wall, its the most rigged tier ever, your players get locked in place giving your opponents an advantage, lag spikes, players running side to side instead of forwards, players running away from the ball when you pass it to them, players running towards a defender without your input allowing a through ball etc**' - and a second voice in the same thread: '**Rigging is quite uniform in tier 1 and 2. The skill level increases significantly in tier 1. It took me three attempts to win tier 1** which is quite a challenge but not impossible. There have been so many players who have won tier 1 10 or 20 times.' (2) THE SHARPEST VERSION - THE FORMATION OVERRIDE: '**S** - The AI will mess up positioning, leaving massive wide open gaps in your defence, and for your offence, **your players will refuse to move forwards. You can pause and change formations all you like, it will fix nothing. The game overrides whatever formation you choose.** This makes it very easy to concede, and very difficult to score. **W** - **Your goalkeeper is nerfed, theirs is boosted.**' So the claim is not that the AI is strong; it is that your own inputs are partly ignored, and your formation changes are cosmetic. (3) THE TIER 1 CADENCE, corroborated a third time: 'I get there probably **once every 4 seasons from tier 2**' - matching the corpus's every-3-4-seasons figure - with the reason: '**in tier 1 there's a huge influx in exploit abusers, c spammers, pacifists etc that make it very hard to win when playing fairly.**' (4) THE NON-MAXED ADVANTAGE, corroborating the corpus's handicap finding from the other side: 'I regularly play with a **full rare team (all maxed to 85-89) in tier 2** and feel like **the game gives you a slight bonus in agility and speed as well as general game luck boost as compared to playing with maxed 92+ players.**' (5) THE RETENTION-HANDICAP THEORY, stated as a theory by a believer: 'When you buy a base card from the market and use him in a career match without upgrading him, how does the player perform? Compared to your maxed cards? In my experience **the difference is huge. The unmaxxed card feels slower, weaker and often is unable to outrun defenders**... **My theory is that ftg intentionally increases the stats of players with weaker teams so that they can have a chance against maxed teams** because if they lose to maxed teams all the time they will lose motivation and most likely quit the game.' Note the observation is about CAREER, where the corpus's own stat model says the difference should be real - so the theory and the mechanic are not cleanly separable. (6) THE LUCK-OVER-SKILL SENTIMENT: 'Scoring is harder for me since day one... Most of the time the winner is whoever got lucky - a lucky ricochet, a lucky goalie save, a lucky rebound, etc. **It feels less like a game of skill this year.**' (7) THE COUNTER-DISSENT, which the corpus must carry beside the rigging claims: 'dont you think smth harder should be added to online playing? i mean, **reaching tier 1 is really simple, u can see lots of ppl who are far away from maxed can easily reach it**, and i m there by a lot of time, hence is quite boring playing.' So the same tier is described as rigged by one player and trivially easy by another - which is the honest shape of the evidence. (8) THE DELIBERATE RELEGATION for farming: 'it had come out DLS 24, the game was totally changed and **I relegated to tier 10 for farming gems and winning events as a break for my mental health.** This June 2024, I returned to play seriously on live, grinding to tier 1.' So dropping to a farming tier is a recognised practice, and it pairs with the corpus's camping rule rather than contradicting it. (9) THE TIER RANGE: '**Tier 1 is the highest while 20 being the lowest**... You match with players in your own tier to have a fair matchmaking process. **I have faced some challenging opponents in tier 8 while some not that good opps in tier 5.**' So the difficulty curve is not monotonic in practice. (10) THE NAMED STADIUMS, which the corpus's capacity ladder was missing: dlsinside's DLS26 stadium table (build 13.420, code 159, last update 2026-09-01) lists real grounds with real capacities - **Brighton / American Express Stadium 43,056 · Fulham / Craven Cottage 29,246 · Gil Vicente / Estádio Cidade de Barcelos** - so the stadium build is a choice of named ground, and the division gates map onto specific clubs. (11) THE FANZONE'S REAL BENEFIT, phrased precisely at last: it grants '**structural discounts on Stadium expansions**' - not a general gem discount, a discount on the sector builds that make up the capacity ladder. That prices the Fanzone directly against the ~10,000-coin stadium project, which is the comparison the corpus needed. (12) THE FANZONE IS AT LEVEL 5 per a mod-site feature list, and its per-level cost remains unpublished - so that gap stands.",
    "WHAT TIER 1 FEELS LIKE, ENUMERATED: players locked in place, running side to side instead of forwards, running away from the ball when passed to, and running towards a defender without input - plus the sharpest claim that the game OVERRIDES WHATEVER FORMATION YOU CHOOSE, so pausing to change shape fixes nothing. THE TIER 1 CADENCE corroborated a third time (once every 4 seasons), with the reason being an influx of exploit abusers and C-spammers. THE NON-MAXED ADVANTAGE corroborated. THE RETENTION-HANDICAP THEORY stated as a theory. AND THE COUNTER-DISSENT that reaching Tier 1 is 'really simple' and boring - the same tier is rigged to one player and trivial to another, and the corpus carries both. THE DELIBERATE RELEGATION TO A FARMING TIER as a recognised practice. THE NAMED STADIUMS (Brighton 43,056, Fulham 29,246) - the capacity ladder is a choice of real ground. THE FANZONE'S REAL BENEFIT: STRUCTURAL DISCOUNTS ON STADIUM EXPANSIONS, which prices it against the ~10,000-coin project directly.",
    "WHAT TIER 1 FEELS LIKE, THE NAMED STADIUMS, AND THE FANZONE'S REAL BENEFIT",
    quality="community")

add_claim("THE TIER 1 COMPLAINT, ENUMERATED - which turns the corpus's scripting discussion from a theory into a list of recognisable behaviours: '**Tier 1 is a bunch of horseshit argue with a wall, its the most rigged tier ever, your players get locked in place giving your opponents an advantage, lag spikes, players running side to side instead of forwards, players running away from the ball when you pass it to them, players running towards a defender without your input allowing a through ball etc**.' **Four specific behaviours to recognise rather than fight** - and a reason the corpus's simple, low-input rules matter more at the top of the ladder than anywhere else.", 3, "dll/tier-1-complaints-enumerated", [e_t1])
add_claim("THE SAME THREAD'S COUNTERWEIGHT: '**Rigging is quite uniform in tier 1 and 2. The skill level increases significantly in tier 1. It took me three attempts to win tier 1** which is quite a challenge but not impossible. **There have been so many players who have won tier 1 10 or 20 times.**' So the tier is beatable, the skill level genuinely rises, and three attempts is a normal cost - which is consistent with the corpus's 3-4 season cadence rather than a wall.", 3, "dll/tier-1-three-attempts-normal", [e_t1])
add_claim("THE SHARPEST VERSION OF THE HANDICAP CLAIM - THE FORMATION OVERRIDE: '**S** - The AI will mess up positioning, leaving massive wide open gaps in your defence, and for your offence, **your players will refuse to move forwards. You can pause and change formations all you like, it will fix nothing. The game overrides whatever formation you choose.** This makes it very easy to concede, and very difficult to score. **W** - **Your goalkeeper is nerfed, theirs is boosted.**' So the claim is not that the AI is strong; it is that **your own inputs are partly ignored and your formation changes are cosmetic**. Recorded as a community claim, not adopted - but it is the most specific statement of the theory in the corpus, and it is testable.", 3, "dll/formation-override-claim", [e_t1], notes="The most specific scripting claim in the corpus; testable by pausing to change shape")
add_claim("THE TIER 1 CADENCE, CORROBORATED A THIRD TIME: 'I get there probably **once every 4 seasons from tier 2**' - matching the corpus's every-3-4-seasons figure - with the reason named: '**in tier 1 there's a huge influx in exploit abusers, c spammers, pacifists etc that make it very hard to win when playing fairly.**' So the top tier is not just harder; it is populated by players using the specific exploits the corpus's counters are built for.", 3, "dll/tier-1-cadence-third-source", [e_t1])
add_claim("THE NON-MAXED ADVANTAGE, corroborating the corpus's handicap finding from the other side: 'I regularly play with a **full rare team (all maxed to 85-89) in tier 2** and feel like **the game gives you a slight bonus in agility and speed as well as general game luck boost as compared to playing with maxed 92+ players.**' A third source for the maxed-squad handicap, and the reason the corpus's stop-coaching advice exists.", 3, "dll/non-maxed-advantage-third-source", [e_t1])
add_claim("THE RETENTION-HANDICAP THEORY, stated as a theory by a believer: 'When you buy a base card from the market and use him in a career match without upgrading him, how does the player perform? Compared to your maxed cards? In my experience **the difference is huge. The unmaxxed card feels slower, weaker and often is unable to outrun defenders**... **My theory is that ftg intentionally increases the stats of players with weaker teams so that they can have a chance against maxed teams** because if they lose to maxed teams all the time they will lose motivation and most likely quit the game.' **Note the observation is about CAREER, where the corpus's own stat model says the difference should be real** - so the theory and the mechanic are not cleanly separable, which is exactly why it stays a theory.", 4, "dll/retention-handicap-theory", [e_t1])
add_claim("THE LUCK-OVER-SKILL SENTIMENT, recorded so the corpus does not oversell skill: 'Scoring is harder for me since day one... Most of the time the winner is whoever got lucky - **a lucky ricochet, a lucky goalie save, a lucky rebound, etc. It feels less like a game of skill this year.**' A DLS26 first-week impression that sits against the record run's pure-skill framing - both are in the corpus because both are reported.", 4, "dll/luck-over-skill-sentiment", [e_t1])
add_claim("THE COUNTER-DISSENT, which the corpus must carry beside the rigging claims: 'dont you think smth harder should be added to online playing? i mean, **reaching tier 1 is really simple, u can see lots of ppl who are far away from maxed can easily reach it**, and i m there by a lot of time, hence is quite boring playing.' **So the same tier is described as rigged by one player and trivially easy by another** - the honest shape of the evidence, and a reason to treat the scripting claims as unproven.", 4, "dll/tier-1-is-simple-counter-dissent", [e_t1])
add_claim("THE DELIBERATE RELEGATION TO A FARMING TIER, a recognised player practice: 'it had come out DLS 24, the game was totally changed and **I relegated to tier 10 for farming gems and winning events as a break for my mental health.** This June 2024, I returned to play seriously on live, grinding to tier 1.' So dropping to a farming tier is a deliberate strategy, and it pairs with the corpus's camping rule rather than contradicting it - the difference is that camping is temporary and this was a season-long break.", 3, "dll/deliberate-relegation-for-farming", [e_t1])
add_claim("THE TIER RANGE AND ITS NON-MONOTONIC DIFFICULTY: '**Tier 1 is the highest while 20 being the lowest**... You match with players in your own tier to have a fair matchmaking process. **I have faced some challenging opponents in tier 8 while some not that good opps in tier 5.**' So the difficulty curve is not monotonic in practice, which is consistent with the corpus's tier-11 cliff and tier-oscillation findings.", 3, "dll/tier-range-and-non-monotonic-difficulty", [e_t1])
add_claim("THE NAMED STADIUMS, which the corpus's capacity ladder was missing: the dlsinside DLS26 stadium table (build 13.420, code 159, last update 2026-09-01) lists real grounds with real capacities - **Brighton / American Express Stadium 43,056 · Fulham / Craven Cottage 29,246 · Gil Vicente / Estadio Cidade de Barcelos**. **So the stadium build is a choice of named ground, and the division gates map onto specific clubs** - which makes the corpus's 6,462-to-90,456 ladder a shopping list rather than an abstraction.", 3, "stadium/named-real-world-grounds", [e_t1])
add_claim("THE FANZONE'S REAL BENEFIT, phrased precisely at last: it grants '**structural discounts on Stadium expansions**' - not a general gem discount, a discount on the **sector builds that make up the capacity ladder**. That prices the Fanzone directly against the ~10,000-coin stadium project, which is the comparison the corpus needed and did not have. The Fanzone is at **level 5** per a mod-site feature list, and **its per-level cost remains unpublished**, so that gap stands.", 3, "facilities/fanzone-structural-stadium-discount", [e_t1], notes="Narrows the Fanzone gap: the benefit is now precise, only the cost is missing")

for p in ['EV-513_tier1_feel.html','EV-513b_named_stadiums_and_fanzone.html']:
    with open(os.path.join(RAW_DIR,p),'w') as fh: fh.write("placeholder\n")

with open(EVIDENCE_INDEX) as f: n_ev=sum(1 for _ in f)
with open(CLAIMS_PATH) as f: n_cl=sum(1 for _ in f)
print(f'Added {cl_id-1-last_cl} claims (CLAIM-{last_cl+1:04d}..CLAIM-{cl_id-1:04d}) and 1 EV (EV-{last_ev+1:03d}). Totals: {n_cl} claims / {n_ev} EVs')
